#!/usr/bin/env python3
"""Generate bounded-scope implementation documentation from reviewed decisions."""
import json,re,collections
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
m=json.loads((ROOT/'manifest.json').read_text());d=json.loads((ROOT/'src/coverage_decisions.json').read_text())
baseline=json.loads((ROOT/'src/gui_expansion_baseline.json').read_text())['icons']
reviewed={r['icon_id'] for r in d if r['decision']=='new-glyph'}
new=[i for i in m['icons'] if i['id'] in reviewed];byid={i['id']:i for i in m['icons']}
counts=dict(collections.Counter(i['decision'] for i in d))
lines=['# Source-scoped GUI coverage implementation','',
 'The source audit is frozen separately: 459 SolidCraft command entries and 630 retrieved SOLIDWORKS documentation appearances, 1,089 evidence rows. It is not a claim about every edition, add-in, context menu or current-year toolbar. Drawing/Table source-year and access limits remain explicit.', '',
 f'This implementation contains **{len(new)} new semantic glyphs**, making **{m["count"]} semantic icons / {m["count"]*2} standalone theme SVG files**. All 449 delivered records and 898 SVG files are preserved byte-for-byte. No count target determines the additions.', '',
 '## Decisions','',f'Reviewed 262 candidate semantic groups were grouped into {len(d)} operation families. Decision counts: '+', '.join(f'{k}: {v}' for k,v in sorted(counts.items()))+'.', '',
 'Style/format/state choices are not multiplied into separate semantic entries. Generic action reuse is accepted only when the action and metaphor remain truthful. Conditional/metadata-only bindings remain uncertain rather than silently being counted as complete.', '',
 '[Complete source-row implementation tracking](GUI_IMPLEMENTATION_TRACKING.csv) preserves original audit classifications and adds separate implementation status, ID and rationale. In particular, the 180 original uncertain rows are not automatically resolved by adding new art.', '',
 '## New glyphs','', '| ID | English / 日本語 | Meaning | Sources |','| --- | --- | --- | --- |']
for i in new:
 refs='; '.join(f'[{key}]({m["sourceReferences"][key]["url"]})' for key in i['sources'])
 lines.append(f'| {i["id"]} | {i["name"]} / {i["nameJa"]} | {i["description"]} | {refs} |')
lines+=['','## Reuse and unresolved decisions','']
for row in d:
 if row['decision']!='new-glyph':lines.append(f'- {row["semantic"]}: {row["decision"]}; {row.get("icon_id","")}. {row["reason"]}')
lines+=['','## Validation','',
 '- Run build.py, test_catalog.py, test_zip.js, test_app.js in both observer modes, raster_audit.py, dark_theme_audit.py and png_export_audit.py.','- The 449-release baseline pins record hashes and both SVG byte hashes; the older 419/410 baselines remain untouched.','- Every one of the 262 audit groups must have exactly one logged implementation decision. Every new glyph must have a reviewed decision and registered source references.','- Native 16/24/32 px light/dark preview pages are generated by coverage_sheet.py. Previews are not browser Canvas screenshots.','- New live-browser, mobile and assistive-technology integration remain unverified. Older Chrome results in QA.md apply to the historical 419 release only.','']
(ROOT/'docs/GUI_COVERAGE.md').write_text('\n'.join(lines))
p=ROOT/'README.md';s=p.read_text();s=s.replace('## GUI expansion (2026-10-24)','## Initial GUI expansion (2026-10-24)').replace('The catalog now contains **449 semantic icons / 898 standalone SVG files**.','That checkpoint contained **449 semantic icons / 898 standalone SVG files**.')
block=f'''<!-- coverage-expansion:start -->
## Systematic GUI coverage (2026-10-25)

{len(new)} new original command glyphs were implemented from the frozen source audit, with documented reuse and unresolved bindings. The current catalog contains **{m['count']} semantic icons / {m['count']*2} standalone SVG files**. All 449 previously delivered records and both theme SVGs remain unchanged.

See [scope, decisions and source mapping](docs/GUI_COVERAGE.md), [all 1,089 evidence rows with implementation status](docs/GUI_IMPLEMENTATION_TRACKING.csv), and [native-size preview page list](qa/coverage-preview/pages.json). This is source-scoped coverage, not a claim that all SOLIDWORKS product editions or every uncertain GUI binding are complete.
<!-- coverage-expansion:end -->'''
if '<!-- coverage-expansion:start -->' in s:s=re.sub(r'<!-- coverage-expansion:start -->.*?<!-- coverage-expansion:end -->',block,s,flags=re.S)
else:s=s.replace('# CAX Iconset','# CAX Iconset\n\n'+block,1)
s=s.replace('- `icons/`: 449 original light SVG files',f'- `icons/`: {m["count"]} original light SVG files')
s=s.replace('今回のGUI拡充後は全449件、186件がモデルツリーに対応します。',f'今回のGUI拡充後は全{m["count"]}件、186件がモデルツリーに対応します。').replace('用途の件数は449件です。',f'用途の件数は{m["count"]}件です。').replace('全449件または絞り込み結果全体を一括保存',f'全{m["count"]}件または絞り込み結果全体を一括保存')
p.write_text(s)
p=ROOT/'docs/QA.md';s=p.read_text();note='Historical 419-release QA record. For the source-scoped GUI additions and current validation limits, see [GUI_COVERAGE.md](GUI_COVERAGE.md).\n\n'
if note not in s:s=note+s
p.write_text(s)
print('Generated coverage decision documentation')
